import { memo, Suspense, type ReactNode } from 'react'

import { useNavigate } from 'react-router-dom'

import { Box, Button, alpha } from '@mui/material'

import { routes } from '@/routes'

import { useGithubCardContextNext } from '../hooks/useFlashCardContent'
import type { ContentIdentifier, ContentItem } from '../types'

import ContentStatus from './ContentStatus'

export type ContentNavigationBarProps = {
  contentId: ContentIdentifier
  content?: ContentItem
  contentPrev?: ContentItem
  contentNext?: ContentItem
  centerButton?: ReactNode
  centerButtonText?: string
  onStartClick?: () => void
  /** 전체 버튼을 잠근다. 학습 기록 저장 중 이탈을 막는 데 쓴다. */
  disabled?: boolean
}

function ContentNavigationBar({
  contentId,
  content,
  contentPrev,
  contentNext,
  centerButton,
  centerButtonText,
  onStartClick,
  disabled = false,
}: ContentNavigationBarProps) {
  const navigate = useNavigate()

  return (
    <Box
      sx={({ palette }) => ({
        position: 'sticky',
        bottom: 0,
        display: 'flex',
        gap: 1,
        mt: 2,
        pt: 2,
        pb: 2,
        borderTop: 1,
        borderColor: 'divider',
        backgroundColor: alpha(palette.background.default, 0.9),
        backdropFilter: 'blur(8px)',
        justifyContent: 'space-evenly',
        zIndex: 10,
        boxShadow: `0 -10px 20px -10px ${alpha(palette.common.black, palette.mode === 'dark' ? 0.5 : 0.1)}`,
      })}
    >
      <Button
        variant="contained"
        size="large"
        onClick={() => {
          navigate(
            routes.flashMan.learn.$({
              owner: contentId.owner,
              repo: contentId.repo,
              path: contentPrev?.path || '',
            })
          )
        }}
        disabled={disabled || !contentPrev}
      >
        이전
        {contentPrev && content && (
          <Suspense>
            {' '}
            <ContentStatus simple content={contentPrev} />
          </Suspense>
        )}
      </Button>
      {centerButton ?? (
        <Button
          variant="contained"
          size="large"
          onClick={onStartClick}
          disabled={disabled || !onStartClick}
        >
          {centerButtonText ?? '시작'}{' '}
          {content && (
            <Suspense>
              {' '}
              <ContentStatus simple content={content} />
            </Suspense>
          )}
        </Button>
      )}
      <Button
        variant="contained"
        size="large"
        onClick={() => {
          navigate(
            routes.flashMan.learn.$({
              owner: contentId.owner,
              repo: contentId.repo,
              path: contentNext?.path || '',
            })
          )
        }}
        disabled={disabled || !contentNext}
      >
        다음
        {contentNext && (
          <Suspense>
            {' '}
            <ContentStatus simple content={contentNext} />
          </Suspense>
        )}
      </Button>
    </Box>
  )
}

export default memo(ContentNavigationBar)

/**
 * Connected version that fetches prev/next content via useGithubCardContextNext.
 */
export type ConnectedContentNavigationBarProps = Pick<
  ContentNavigationBarProps,
  'contentId' | 'centerButton' | 'centerButtonText' | 'onStartClick' | 'disabled'
>

function ConnectedContentNavigationBarInner({
  contentId,
  ...rest
}: ConnectedContentNavigationBarProps) {
  const { content, contentPrev, contentNext } = useGithubCardContextNext(contentId)

  return (
    <ContentNavigationBar
      contentId={contentId}
      content={content}
      contentPrev={contentPrev}
      contentNext={contentNext}
      {...rest}
    />
  )
}

export const ConnectedContentNavigationBar = memo(ConnectedContentNavigationBarInner)
